395	// registryRef is what an entry is displayed as: its address, not its URL.
396	//
397	// The prefix has to be on screen or the tab says nothing useful — one line per
398	// proxy is one host repeated, and a group's members all answer to the same host
399	// too (§3.18). Joined with a slash because that is exactly the head of the pull
400	// reference: `docker pull nexus.example.com/dhi-io-proxy/eclipse-temurin:21`.
401	// Plain text only — Rule 122.
402	func registryRef(url, repoPrefix string) string {
403		if repoPrefix == "" {
404			return url
405		}
406		return strings.TrimSuffix(url, "/") + "/" + repoPrefix
407	}
