409	// membersCell reports what the last discovery for a group found, and when.
410	//
411	// The "when" is not decoration: a cache with no visible age is worse than the
412	// re-detection it replaced, because it looks current whatever it holds
413	// (§3.8, decision 3). Plain text only — Rule 122.
414	func (m *Model) membersCell(reg config.RegistryItem) string {
415		if reg.Kind != config.KindGroup {
416			return ""
417		}
418		if m.refreshingGroups[reg.Slug] {
419			// Static text: the row's dot is the animation (Rule 122).
420			return "refreshing"
421		}
422		entry, ok := m.groupCache[reg.Slug]
423		if !ok {
424			return "never" // declared a group, never asked
425		}
426		return fmt.Sprintf("%d · %s", len(entry.Members), timeAgo(entry.DiscoveredAt))
427	}
